class Vector3 {
  constructor(x = 0, y = 0, z = 0) { this.x = +x; this.y = +y; this.z = +z; }
  static new(x, y, z) { return new Vector3(x, y, z); }
  add(o) { return new Vector3(this.x + o.x, this.y + o.y, this.z + o.z); }
  sub(o) { return new Vector3(this.x - o.x, this.y - o.y, this.z - o.z); }
  mul(o) { return typeof o === 'number' ? new Vector3(this.x * o, this.y * o, this.z * o) : new Vector3(this.x * o.x, this.y * o.y, this.z * o.z); }
  div(o) { return typeof o === 'number' ? new Vector3(this.x / o, this.y / o, this.z / o) : new Vector3(this.x / o.x, this.y / o.y, this.z / o.z); }
  get Magnitude() { return Math.hypot(this.x, this.y, this.z); }
  get Unit() { const m = this.Magnitude || 1; return new Vector3(this.x / m, this.y / m, this.z / m); }
  Dot(o) { return this.x * o.x + this.y * o.y + this.z * o.z; }
  Cross(o) { return new Vector3(this.y * o.z - this.z * o.y, this.z * o.x - this.x * o.z, this.x * o.y - this.y * o.x); }
  Lerp(o, t) { return new Vector3(this.x + (o.x - this.x) * t, this.y + (o.y - this.y) * t, this.z + (o.z - this.z) * t); }
  equals(o) { return o instanceof Vector3 && o.x === this.x && o.y === this.y && o.z === this.z; }
  toArray() { return [this.x, this.y, this.z]; }
  toString() { return `${this.x}, ${this.y}, ${this.z}`; }
}
class Color3 {
  constructor(r = 0, g = 0, b = 0) { this.r = +r; this.g = +g; this.b = +b; }
  static new(r, g, b) { return new Color3(r, g, b); }
  static fromRGB(r, g, b) { return new Color3(r / 255, g / 255, b / 255); }
  static fromHex(h) { return new Color3((h >> 16 & 255) / 255, (h >> 8 & 255) / 255, (h & 255) / 255); }
  equals(o) { return o instanceof Color3 && o.r === this.r && o.g === this.g && o.b === this.b; }
  toArray() { return [this.r, this.g, this.b]; }
  toString() { return `${this.r}, ${this.g}, ${this.b}`; }
}

// A sandboxed Lua/Luau-style interpreter (lexer, parser, tree-walking evaluator) bound to the data model.
// Supported: locals, functions/closures, varargs, multiple returns, tables, numeric/generic for, while/repeat, if/elseif, continue,
// compound assignment (+= -= *= /= ..=), string methods, pcall/error. Not supported: coroutines/yielding wait(), metatables, goto, type annotations.
