// ---------------------------------------------------------------- lexer
const KEYWORDS = new Set(['and', 'break', 'continue', 'do', 'else', 'elseif', 'end', 'false', 'for', 'function', 'if', 'in', 'local', 'nil', 'not', 'or', 'repeat', 'return', 'then', 'true', 'until', 'while']);
function lex(src) {
  const toks = []; let i = 0, line = 1; const n = src.length;
