        if (src[i] === '\\') {
          i++; const e = src[i];
          if (e === 'n') s += '\n'; else if (e === 't') s += '\t'; else if (e === 'r') s += '\r'; else if (e === '0') s += '\0'; else if (e === 'x') { s += String.fromCharCode(parseInt(src.slice(i + 1, i + 3), 16)); i += 2; }
          else if (/\d/.test(e)) { const m = /^\d{1,3}/.exec(src.slice(i)); s += String.fromCharCode(+m[0]); i += m[0].length - 1; } else s += e;
