    if (['==', '~=', '<=', '>=', '..', '//', '+=', '-=', '*=', '/='].includes(two)) { toks.push({ t: 'op', v: two, line }); i += 2; continue; }
    if ('+-*/%^#<>=(){}[];:,.'.includes(c)) { toks.push({ t: 'op', v: c, line }); i++; continue; }
