const BIN = { 'or': [1, 1], 'and': [2, 2], '<': [3, 3], '>': [3, 3], '<=': [3, 3], '>=': [3, 3], '~=': [3, 3], '==': [3, 3], '..': [9, 8], '+': [10, 10], '-': [10, 10], '*': [11, 11], '/': [11, 11], '//': [11, 11], '%': [11, 11], '^': [14, 13] };
function parse(src) {
  const toks = lex(src); let p = 0;
  const peek = () => toks[p], next = () => toks[p++];
  const fail = (m, t = peek()) => { throw new LuaError(`[string]:${t.line}: ${m} near '${t.v}'`); };
  const isOp = v => peek().t === 'op' && peek().v === v, isKw = v => peek().t === 'kw' && peek().v === v;
  const accept = v => { if ((peek().t === 'op' || peek().t === 'kw') && peek().v === v) { p++; return true; } return false; };
  const expect = v => { if (!accept(v)) fail(`'${v}' expected`); };
  const name = () => { if (peek().t !== 'name') fail('name expected'); return next().v; };
  const blockEnd = () => { const t = peek(); return t.t === 'eof' || (t.t === 'kw' && ['end', 'else', 'elseif', 'until'].includes(t.v)); };
