      const t = db.transaction(['blobs', 'meta'], 'readwrite'), order = keys.map((k, i) => [k, vals[i]]).sort((a, b) => a[1].t - b[1].t);
      for (const [k, v] of order) { if (total <= LIMIT * 0.8) break; t.objectStore('blobs').delete(k); t.objectStore('meta').delete(k); total -= v.size; } } catch (e) {} };
