@group(0) @binding(3) var shadowSamp: sampler_comparison;
@group(0) @binding(4) var skyTex: texture_2d_array<f32>;   // layers: back, down, front, left, right, top
@group(0) @binding(5) var skySamp: sampler;
@group(0) @binding(6) var matTex: texture_2d_array<f32>;   // streamed images, one layer each

// ---------------- sky ----------------
fn hash2(p: vec2u) -> f32 {
  var h = p.x * 374761393u + p.y * 668265263u;
  h = (h ^ (h >> 13u)) * 1274126177u;
  return f32(h ^ (h >> 16u)) / 4294967295.0;
}
fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let ip = vec2i(i);
  let a = hash2(bitcast<vec2u>(ip));
  let b = hash2(bitcast<vec2u>(ip + vec2i(1, 0)));
  let c = hash2(bitcast<vec2u>(ip + vec2i(0, 1)));
  let d = hash2(bitcast<vec2u>(ip + vec2i(1, 1)));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
fn fbm(p: vec2f) -> f32 {
  var a = 0.5;
  var s = 0.0;
  var q = p;
  for (var i = 0; i < 5; i++) { s += a * vnoise(q); q = q * 2.03 + vec2f(17.0, 9.0); a *= 0.5; }
  return s / 0.96875;
}

// Soft blue gradient with a bright, hazy horizon band (also used for ambient, reflections and distance haze).
fn skyGradient(d: vec3f) -> vec3f {
  let e = d.y;
  let zen = pow(vec3f(0.36, 0.58, 0.86), vec3f(2.2));
  let mid = pow(vec3f(0.45, 0.72, 0.93), vec3f(2.2));
  let hor = pow(vec3f(0.80, 0.91, 0.95), vec3f(2.2));
  let low = pow(vec3f(0.50, 0.80, 0.94), vec3f(2.2));
  var c = mix(hor, mid, smoothstep(0.0, 0.18, e));
  c = mix(c, zen, smoothstep(0.1, 0.9, e));
  return mix(c, low, smoothstep(0.0, 0.5, -e));
}
// Procedural sky: gradient + wispy streaks near the horizon, puffs overhead, soft sun.
fn skyProc(d: vec3f) -> vec3f {
  var c = skyGradient(d);
  let up = max(d.y, 0.0);
  let p = d.xz / (up + 0.18);
  let n = fbm(p * vec2f(0.55, 1.4) + vec2f(3.0, 7.0));
  let cov = smoothstep(0.50, 0.78, n) * smoothstep(0.0, 0.12, d.y);
  let lit = clamp(0.55 + 0.45 * dot(normalize(vec3f(d.x, up + 0.3, d.z)), F.sunDir.xyz), 0.0, 1.0);
  let cloud = mix(pow(vec3f(0.72, 0.80, 0.88), vec3f(2.2)), pow(vec3f(0.97, 0.98, 0.98), vec3f(2.2)), lit);
  c = mix(c, cloud, cov * 0.9);
  let s = max(dot(d, F.sunDir.xyz), 0.0);
  return c + F.sunColor.rgb * (pow(s, 900.0) * 0.8 + pow(s, 12.0) * 0.03);
}
// Six-face skybox lookup. Faces follow the sheet order: back, down, front, left, right, top.
// Front is -Z (the way the camera looks at yaw 0), right is +X, up is +Y.
fn skyTexColor(d: vec3f) -> vec3f {
  let a = abs(d);
  var layer = 0;
  var uv = vec2f(0.0);
  if (a.z >= a.x && a.z >= a.y) {
    if (d.z < 0.0) { layer = 2; uv = vec2f(d.x / a.z, -d.y / a.z); }
    else { layer = 0; uv = vec2f(-d.x / a.z, -d.y / a.z); }
  } else if (a.x >= a.y) {
    if (d.x > 0.0) { layer = 4; uv = vec2f(d.z / a.x, -d.y / a.x); }
    else { layer = 3; uv = vec2f(-d.z / a.x, -d.y / a.x); }
  } else {
    if (d.y > 0.0) { layer = 5; uv = vec2f(d.x / a.y, -d.z / a.y); }
    else { layer = 1; uv = vec2f(d.x / a.y, d.z / a.y); }
  }
  let t = clamp(uv * 0.5 + 0.5, vec2f(0.001), vec2f(0.999));
  return textureSampleLevel(skyTex, skySamp, t, layer, 0.0).rgb;
}
fn skyBg(d: vec3f) -> vec3f {
  if (F.haze.y > 0.5) { return skyTexColor(d); }
  return skyProc(d);
}
fn skyEnv(d: vec3f) -> vec3f {
  if (F.haze.y > 0.5) { return skyTexColor(d); }
  return skyGradient(d);
}

// ---------------- geometry ----------------
struct VOut {
  @builtin(position) pos: vec4f,
  @location(0) wpos: vec3f, @location(1) nrm: vec3f,
  @location(2) color: vec4f, @location(3) @interpolate(flat) params: vec4f, @location(4) uv: vec2f,
}
@vertex fn vs_main(@location(0) p: vec3f, @location(1) n: vec3f, @location(2) uv: vec2f, @builtin(instance_index) ii: u32) -> VOut {
  let I = inst[ii];
  let w = I.model * vec4f(p, 1.0);
  let a = I.model[0].xyz; let b = I.model[1].xyz; let c = I.model[2].xyz;
  var o: VOut;
  o.pos = F.viewProj * w;
  o.wpos = w.xyz;
  o.nrm = normalize(cross(b, c) * n.x + cross(c, a) * n.y + cross(a, b) * n.z); // cofactor = inverse-transpose
  o.color = I.color; o.params = I.params; o.uv = uv;
  return o;
}

// Sun: 3 cascaded shadow maps, 3x3 PCF.
fn shadow(wp: vec3f, n: vec3f) -> f32 {
  let d = dot(wp - F.camPos.xyz, F.camFwd.xyz);
  var idx = 2;
  if (d < F.splits.x) { idx = 0; } else if (d < F.splits.y) { idx = 1; }
  let lp = F.cascadeVP[idx] * vec4f(wp + n * (0.03 + 0.04 * f32(idx)), 1.0);
  let uv = vec2f(lp.x * 0.5 + 0.5, 0.5 - lp.y * 0.5);
  var s = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      s += textureSampleCompareLevel(shadowTex, shadowSamp, uv + vec2f(f32(x), f32(y)) * F.proj.w, idx, lp.z);
    }
  }
  let inside = select(0.0, 1.0, uv.x > 0.0 && uv.x < 1.0 && uv.y > 0.0 && uv.y < 1.0 && lp.z < 1.0);
  return mix(1.0, s / 9.0, inside);
}

fn dGGX(nh: f32, a: f32) -> f32 { let a2 = a * a; let d = nh * nh * (a2 - 1.0) + 1.0; return a2 / (PI * d * d); }
fn gSmith(nv: f32, nl: f32, r: f32) -> f32 {
  let k = (r + 1.0) * (r + 1.0) / 8.0;
  return (nv / (nv * (1.0 - k) + k)) * (nl / (nl * (1.0 - k) + k));
}
fn fSchlick(c: f32, f0: vec3f) -> vec3f { return f0 + (vec3f(1.0) - f0) * pow(1.0 - c, 5.0); }
// Cook-Torrance (already multiplied by N.L).
fn brdf(N: vec3f, V: vec3f, L: vec3f, alb: vec3f, rough: f32, metal: f32) -> vec3f {
  let H = normalize(V + L);
  let f0 = mix(vec3f(0.04), alb, metal);
  let nl = max(dot(N, L), 0.0);
  let nv = max(dot(N, V), 0.0001);
  let fr = fSchlick(max(dot(V, H), 0.0), f0);
  let spec = dGGX(max(dot(N, H), 0.0), rough * rough) * gSmith(nv, nl, rough) * fr / (4.0 * nv * max(nl, 0.0001));
  return ((vec3f(1.0) - fr) * (1.0 - metal) * alb / PI + spec) * nl;
}

// Flat studs on top faces (1-stud grid), fading with distance so they never shimmer. Returns perturbed normal + mark.
fn stud(wp: vec3f, n: vec3f, dist: f32, studOn: f32) -> vec4f {
  let fade = (1.0 - smoothstep(25.0, 75.0, dist)) * studOn * select(0.0, 1.0, n.y > 0.95);
  let c = fract(wp.xz) - vec2f(0.5);
  let r = length(c) / 0.3;
  let dir = c / max(length(c), 0.0001);
  let tilt = smoothstep(0.88, 1.0, r) * select(0.0, 1.0, r < 1.0) * 1.6 * fade;
  let mark = select(0.0, 1.0, abs(c.x) < 0.075 && abs(c.y) < 0.075) * fade;
  return vec4f(normalize(n + vec3f(dir.x, 0.0, dir.y) * tilt), mark);
}

@fragment fn fs_main(i: VOut) -> @location(0) vec4f {
  let dist = length(F.camPos.xyz - i.wpos);
  let n0 = normalize(i.nrm);
  let st = stud(i.wpos, n0, dist, select(0.0, 1.0, fract(i.params.w * 0.5) > 0.25));
  let N = st.xyz;
  let V = normalize(F.camPos.xyz - i.wpos);
  let rough = clamp(i.params.x, 0.05, 1.0);
  let metal = i.params.y;
  var alb = pow(i.color.rgb, vec3f(2.2)) * (1.0 - 0.15 * st.w);
  let tl = i32(floor(i.params.w * 0.5)) - 1;   // params.w = studs flag + 2 x (texture layer + 1)
  if (tl >= 0) { alb = alb * textureSampleLevel(matTex, skySamp, i.uv, tl, 0.0).rgb; }
  var col = brdf(N, V, F.sunDir.xyz, alb, rough, metal) * F.sunColor.rgb * shadow(i.wpos, n0);
  // Ambient: bright sky hemisphere from above, warm bounce from below, plus a rough-attenuated sky reflection.
  let f0 = mix(vec3f(0.04), alb, metal);
  let fa = fSchlick(max(dot(N, V), 0.0001), f0);
  let hemi = mix(GND_AMB, SKY_AMB, N.y * 0.5 + 0.5);
  col += (vec3f(1.0) - fa) * (1.0 - metal) * alb * hemi * 0.9;
  col += skyEnv(reflect(-V, N)) * fa * mix(1.0, 0.2, rough);
  col += alb * i.params.z;
  // Distance haze fades into the horizon band of the sky.
  let vd = normalize(i.wpos - F.camPos.xyz);
  let hz = skyEnv(normalize(vec3f(vd.x, 0.03, vd.z)));
  col = mix(col, hz, (1.0 - exp(-F.haze.x * dist)) * exp(-max(i.wpos.y, 0.0) * 0.01));
  return vec4f(col, i.color.a);
}

struct SkyOut { @builtin(position) pos: vec4f, @location(0) ndc: vec2f }
@vertex fn vs_sky(@builtin(vertex_index) i: u32) -> SkyOut {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var o: SkyOut; o.pos = vec4f(p[i], 1.0, 1.0); o.ndc = p[i]; return o;
}
@fragment fn fs_sky(i: SkyOut) -> @location(0) vec4f {
  let d = normalize(F.camFwd.xyz + F.camRight.xyz * (i.ndc.x * F.proj.x * F.proj.y) + F.camUp.xyz * (i.ndc.y * F.proj.x));
  return vec4f(skyBg(d), 1.0);
}
`;

const SHADOW = /* wgsl */`
struct Inst { model: mat4x4f, color: vec4f, params: vec4f }
struct VP { m: mat4x4f }
@group(0) @binding(0) var<uniform> vp: VP;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@vertex fn vs_shadow(@location(0) p: vec3f, @builtin(instance_index) ii: u32) -> @builtin(position) vec4f {
  return vp.m * inst[ii].model * vec4f(p, 1.0);
}
`;

const POST = /* wgsl */`
@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var tex: texture_2d<f32>;
@group(0) @binding(2) var tex2: texture_2d<f32>;
struct PO { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
@vertex fn vs(@builtin(vertex_index) i: u32) -> PO {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var o: PO; o.pos = vec4f(p[i], 0.0, 1.0); o.uv = vec2f(p[i].x * 0.5 + 0.5, 0.5 - p[i].y * 0.5); return o;
}
fn tap(uv: vec2f) -> vec3f { return textureSampleLevel(tex, samp, uv, 0.0).rgb; }
fn box4(uv: vec2f) -> vec3f {
  let ts = 1.0 / vec2f(textureDimensions(tex));
  return 0.25 * (tap(uv + ts * vec2f(-1.0, -1.0)) + tap(uv + ts * vec2f(1.0, -1.0)) + tap(uv + ts * vec2f(-1.0, 1.0)) + tap(uv + ts * vec2f(1.0, 1.0)));
}
@fragment fn fs_pre(i: PO) -> @location(0) vec4f {   // only energy above 1.0 blooms (sun, hot highlights)
  let c = box4(i.uv); let l = max(c.r, max(c.g, c.b));
  return vec4f(min(c * (max(l - 1.0, 0.0) / max(l, 0.0001)), vec3f(50.0)), 1.0);
}
@fragment fn fs_down(i: PO) -> @location(0) vec4f { return vec4f(box4(i.uv), 1.0); }
@fragment fn fs_up(i: PO) -> @location(0) vec4f { return vec4f(box4(i.uv), 1.0); } // additive blend

fn aces(x: vec3f) -> vec3f {
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), vec3f(0.0), vec3f(1.0));
}
fn srgb(c: vec3f) -> vec3f { return select(1.055 * pow(c, vec3f(1.0 / 2.4)) - 0.055, c * 12.92, c <= vec3f(0.0031308)); }
@fragment fn fs_comp(i: PO) -> @location(0) vec4f {
  let hdr = (textureSampleLevel(tex, samp, i.uv, 0.0).rgb + textureSampleLevel(tex2, samp, i.uv, 0.0).rgb * 0.3) * 1.25;
  var c = aces(hdr);
  let l = dot(c, vec3f(0.2126, 0.7152, 0.0722));
  c = mix(vec3f(l), c, 1.12) * vec3f(1.03, 1.0, 0.96);       // saturated, slightly warm
  return vec4f(srgb(c), 1.0);
}
`;

// Crimson web renderer, FigureBlox-style look. WebGPU, HDR, 4x MSAA, PBR, 3 sun cascades with PCF,
// procedural or six-face skybox, distance haze into the sky's horizon band, soft bloom, filmic tone map.



const SHAPE_CAP = { cube: 4096, sphere: 1024, cylinder: 1024, wedge: 1024, cone: 1024 }, GLASS_CAP = 256, CASCADES = 3, SHADOW_SIZE = 2048, BLOOM = 5, REACH = 200, MSAA = 4, SKY_SIZE = 1024;
const ADD = { color: { srcFactor: 'one', dstFactor: 'one', operation: 'add' }, alpha: { srcFactor: 'one', dstFactor: 'one', operation: 'add' } };

class Renderer {
  static async create(canvas) { const r = new Renderer(canvas); await r.init(); return r; }
  constructor(canvas) { this.canvas = canvas; this.w = 0; this.h = 0; this.skyMode = 0; this.onError = null; }

  _buf(data, usage) {
    const b = this.device.createBuffer({ size: data.byteLength, usage: usage | GPUBufferUsage.COPY_DST });
    this.device.queue.writeBuffer(b, 0, data); return b;
  }

  async init() {
    const adapter = await navigator.gpu?.requestAdapter();
    if (!adapter) throw new Error('WebGPU is not available in this browser.');
    const d = this.device = await adapter.requestDevice();
    d.lost.then(i => console.error('GPU device lost:', i.message));
    d.onuncapturederror = e => { console.error(e.error.message); this.onError?.(e.error.message); };
    this.ctx = this.canvas.getContext('webgpu');
    this.format = navigator.gpu.getPreferredCanvasFormat();
    this.ctx.configure({ device: d, format: this.format, alphaMode: 'opaque' });

    const U = GPUBufferUsage, T = GPUTextureUsage;
    const g = buildGeometry(); this.shapes = g.shapes;
    // One big vertex and index buffer: the primitives sit at the start, streamed meshes are sub-allocated behind them.
    this.vb = d.createBuffer({ size: VERT_POOL * 32, usage: U.VERTEX | U.COPY_DST }); d.queue.writeBuffer(this.vb, 0, g.vertices); this.vAlloc = new RangeAlloc(VERT_POOL, g.vertices.length / 8);
    this.ib = d.createBuffer({ size: IDX_POOL * 4, usage: U.INDEX | U.COPY_DST }); d.queue.writeBuffer(this.ib, 0, g.indices); this.iAlloc = new RangeAlloc(IDX_POOL, g.indices.length);
    this.meshDraws = new Map(); this.meshFree = []; this.meshNext = 0;
    // One instance buffer, carved into a fixed region per shape. Parts are written to individual slots as the data model changes.
    this.base = {}; this.counts = {}; let total = 0; for (const n of Object.keys(this.shapes)) { this.base[n] = total; this.counts[n] = 0; total += SHAPE_CAP[n]; }
    for (const n of Object.keys(this.shapes)) { this.base[n + '~'] = total; this.counts[n + '~'] = 0; total += GLASS_CAP; }   // '~' = glass region (alpha-blended)
    this.meshBase = total; total += MESH_CAP;                                      // instance slots for streamed meshes (one draw call each)
    this.mirror = new Float32Array(total * 24);
    this.instBuf = d.createBuffer({ size: total * 96, usage: U.STORAGE | U.COPY_DST });
    this.frame = d.createBuffer({ size: 100 * 4, usage: U.UNIFORM | U.COPY_DST });
    const vbl = { arrayStride: 32, attributes: [{ shaderLocation: 0, offset: 0, format: 'float32x3' }, { shaderLocation: 1, offset: 12, format: 'float32x3' }, { shaderLocation: 2, offset: 24, format: 'float32x2' }] };
    const depth = { format: 'depth32float', depthWriteEnabled: true, depthCompare: 'less' };
    const ms = { count: MSAA };

    const sm = d.createShaderModule({ code: SCENE }), shm = d.createShaderModule({ code: SHADOW }), pm = d.createShaderModule({ code: POST });
    for (const [name, mod] of [['scene', sm], ['shadow', shm], ['post', pm]]) { // surface WGSL errors instead of rendering black
      const info = await mod.getCompilationInfo(), err = info.messages.find(m => m.type === 'error');
      if (err) throw new Error(`${name} shader, line ${err.lineNum}: ${err.message}`);
    }

    this.cascadeBuf = [...Array(CASCADES)].map(() => d.createBuffer({ size: 64, usage: U.UNIFORM | U.COPY_DST }));
    const shadowTex = d.createTexture({ size: [SHADOW_SIZE, SHADOW_SIZE, CASCADES], format: 'depth32float', usage: T.RENDER_ATTACHMENT | T.TEXTURE_BINDING });
    this.shadowArr = shadowTex.createView({ dimension: '2d-array' });
    this.shadowViews = [...Array(CASCADES)].map((_, i) => shadowTex.createView({ dimension: '2d', baseArrayLayer: i, arrayLayerCount: 1 }));
    this.cmp = d.createSampler({ compare: 'less-equal', magFilter: 'linear', minFilter: 'linear' });
    this.linear = d.createSampler({ magFilter: 'linear', minFilter: 'linear', addressModeU: 'clamp-to-edge', addressModeV: 'clamp-to-edge' });
    this.skySamp = this.linear;

    const hdr = [{ format: 'rgba16float' }];
    this.scenePipe = d.createRenderPipeline({ layout: 'auto', vertex: { module: sm, entryPoint: 'vs_main', buffers: [vbl] },
      fragment: { module: sm, entryPoint: 'fs_main', targets: hdr }, primitive: { cullMode: 'back' }, depthStencil: depth, multisample: ms });
    this.skyPipe = d.createRenderPipeline({ layout: 'auto', vertex: { module: sm, entryPoint: 'vs_sky' }, fragment: { module: sm, entryPoint: 'fs_sky', targets: hdr },
      depthStencil: { format: 'depth32float', depthWriteEnabled: false, depthCompare: 'less-equal' }, multisample: ms });
    const blend = { color: { srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add' }, alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' } };
    this.glassPipe = d.createRenderPipeline({ layout: 'auto', vertex: { module: sm, entryPoint: 'vs_main', buffers: [vbl] },
      fragment: { module: sm, entryPoint: 'fs_main', targets: [{ format: 'rgba16float', blend }] }, primitive: { cullMode: 'back' },
      depthStencil: { format: 'depth32float', depthWriteEnabled: false, depthCompare: 'less' }, multisample: ms });
    this.shadowPipe = d.createRenderPipeline({ layout: 'auto', vertex: { module: shm, entryPoint: 'vs_shadow', buffers: [vbl] }, primitive: { cullMode: 'back' },
      depthStencil: { ...depth, depthBias: 1, depthBiasSlopeScale: 1.5 } });
    const post = (entry, format, blend) => d.createRenderPipeline({ layout: 'auto', vertex: { module: pm, entryPoint: 'vs' },
      fragment: { module: pm, entryPoint: entry, targets: [{ format, blend }] } });
    this.pre = post('fs_pre', 'rgba16float'); this.down = post('fs_down', 'rgba16float');
    this.up = post('fs_up', 'rgba16float', ADD); this.comp = post('fs_comp', this.format);

    this.shadowBG = this.cascadeBuf.map(b => d.createBindGroup({ layout: this.shadowPipe.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: { buffer: b } }, { binding: 1, resource: { buffer: this.instBuf } }] }));
    this.matTex = d.createTexture({ size: [TEX_SIZE, TEX_SIZE, TEX_LAYERS], format: 'rgba8unorm-srgb', usage: T.TEXTURE_BINDING | T.COPY_DST | T.RENDER_ATTACHMENT });   // the texture array: one layer per streamed image
    this.matView = this.matTex.createView({ dimension: '2d-array' });
    this._setSkyTexture(d.createTexture({ size: [1, 1, 6], format: 'rgba8unorm-srgb', usage: T.TEXTURE_BINDING | T.COPY_DST }));  // placeholder until a skybox is loaded
  }

  _setSkyTexture(tex) {
    const d = this.device;
    this.skyTexObj?.destroy(); this.skyTexObj = tex;
    const sky = tex.createView({ dimension: '2d-array' }), fr = { binding: 0, resource: { buffer: this.frame } };
    this.sceneBG = d.createBindGroup({ layout: this.scenePipe.getBindGroupLayout(0), entries: [fr, { binding: 1, resource: { buffer: this.instBuf } },
      { binding: 2, resource: this.shadowArr }, { binding: 3, resource: this.cmp }, { binding: 4, resource: sky }, { binding: 5, resource: this.skySamp }, { binding: 6, resource: this.matView }] });
    this.glassBG = d.createBindGroup({ layout: this.glassPipe.getBindGroupLayout(0), entries: [fr, { binding: 1, resource: { buffer: this.instBuf } },
      { binding: 2, resource: this.shadowArr }, { binding: 3, resource: this.cmp }, { binding: 4, resource: sky }, { binding: 5, resource: this.skySamp }, { binding: 6, resource: this.matView }] });
    this.skyBG = d.createBindGroup({ layout: this.skyPipe.getBindGroupLayout(0), entries: [fr, { binding: 4, resource: sky }, { binding: 5, resource: this.skySamp }] });
  }

  // Load a skybox from one image holding six faces in a 2-column x 3-row sheet, row by row:
  //   back, down / front, left / right, top.  A small margin is trimmed from each cell to drop separator lines.
  async setSkyboxFromBlob(blob) {
    const d = this.device, bmp = await createImageBitmap(blob);
    const cw = bmp.width / 2, ch = bmp.height / 3, inset = Math.round(Math.min(cw, ch) * 0.008) + 1;
    const tex = d.createTexture({ size: [SKY_SIZE, SKY_SIZE, 6], format: 'rgba8unorm-srgb',
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST | GPUTextureUsage.RENDER_ATTACHMENT });
    for (let k = 0; k < 6; k++) {
      const face = await createImageBitmap(bmp, Math.round((k % 2) * cw + inset), Math.round(Math.floor(k / 2) * ch + inset),
        Math.round(cw - 2 * inset), Math.round(ch - 2 * inset), { resizeWidth: SKY_SIZE, resizeHeight: SKY_SIZE, resizeQuality: 'high' });
      d.queue.copyExternalImageToTexture({ source: face }, { texture: tex, origin: [0, 0, k] }, [SKY_SIZE, SKY_SIZE]);
      face.close();
    }
    bmp.close(); this._setSkyTexture(tex); this.skyMode = 1;
  }
  setSkyboxProcedural() { this.skyMode = 0; }

  _resize(w, h) {
    const d = this.device, T = GPUTextureUsage, RT = T.RENDER_ATTACHMENT | T.TEXTURE_BINDING;
    [this.msaaTex, this.depthTex, this.hdrTex, ...(this.bloom || [])].forEach(t => t?.destroy());
    const tex = (w, h, format, usage, sampleCount = 1) => d.createTexture({ size: [w, h], format, usage, sampleCount });
    this.msaaTex = tex(w, h, 'rgba16float', T.RENDER_ATTACHMENT, MSAA); this.depthTex = tex(w, h, 'depth32float', T.RENDER_ATTACHMENT, MSAA);
    this.hdrTex = tex(w, h, 'rgba16float', RT);
    this.bloom = [...Array(BLOOM)].map((_, i) => tex(Math.max(1, w >> (i + 1)), Math.max(1, h >> (i + 1)), 'rgba16float', RT));
    this.msaaV = this.msaaTex.createView(); this.depthV = this.depthTex.createView(); this.hdrV = this.hdrTex.createView(); this.bloomV = this.bloom.map(t => t.createView());
    const bg = (p, ...views) => d.createBindGroup({ layout: p.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: this.linear }, ...views.map((v, i) => ({ binding: i + 1, resource: v }))] });
    this.preBG = bg(this.pre, this.hdrV);
    this.downBG = this.bloomV.map(v => bg(this.down, v)); this.upBG = this.bloomV.map(v => bg(this.up, v));
    this.compBG = bg(this.comp, this.hdrV, this.bloomV[0]);
    this.w = w; this.h = h;
  }

  // ---- instance slots (driven by SceneSync from data-model change signals)
  allocSlot(shape, glass = false) { const k = glass ? shape + '~' : shape, cap = glass ? GLASS_CAP : SHAPE_CAP[shape]; if (this.counts[k] >= cap) throw new Error(`Too many ${k} parts (max ${cap})`); return this.base[k] + this.counts[k]++; }
  freeSlot(shape, slot, glass = false) {                                // swap-remove keeps each region's run contiguous; returns the slot that was moved into `slot`, if any
    const k = glass ? shape + '~' : shape, last = this.base[k] + --this.counts[k]; if (last === slot) return null;
    this.mirror.copyWithin(slot * 24, last * 24, last * 24 + 24); this.device.queue.writeBuffer(this.instBuf, slot * 96, this.mirror, slot * 24, 24); return last;
  }
  // ---- streamed meshes: ranges in the shared pools, one instance slot each, drawn individually
  uploadMesh(m) {
    const nv = m.v.length / 8, v = this.vAlloc.alloc(nv), i = this.iAlloc.alloc(m.i.length);
    if (v < 0 || i < 0) { if (v >= 0) this.vAlloc.put(v, nv); if (i >= 0) this.iAlloc.put(i, m.i.length); return null; }
    this.device.queue.writeBuffer(this.vb, v * 32, m.v); this.device.queue.writeBuffer(this.ib, i * 4, m.i); return { v, nv, i, ni: m.i.length };
  }
  freeMesh(h) { this.vAlloc.put(h.v, h.nv); this.iAlloc.put(h.i, h.ni); }
  allocMeshSlot(h) { const s = this.meshFree.pop() ?? (this.meshNext < MESH_CAP ? this.meshNext++ : -1); if (s < 0) return -1; const slot = this.meshBase + s; this.meshDraws.set(slot, h); return slot; }
  freeMeshSlot(slot) { this.meshDraws.delete(slot); this.meshFree.push(slot - this.meshBase); }
  writeLayer(layer, bitmap) { this.device.queue.copyExternalImageToTexture({ source: bitmap }, { texture: this.matTex, origin: [0, 0, layer] }, [TEX_SIZE, TEX_SIZE]); }
  writeSlot(slot, data) { this.mirror.set(data, slot * 24); this.device.queue.writeBuffer(this.instBuf, slot * 96, data); }
  get instanceCount() { return Object.values(this.counts).reduce((a, b) => a + b, 0); }
  _draw(p, glass = false) {
    p.setVertexBuffer(0, this.vb); p.setIndexBuffer(this.ib, 'uint32');
    for (const [n, s] of Object.entries(this.shapes)) { const k = glass ? n + '~' : n; if (this.counts[k]) p.drawIndexed(s.count, this.counts[k], s.first, s.base, this.base[k]); }
    if (!glass) for (const [slot, h] of this.meshDraws) p.drawIndexed(h.ni, 1, h.i, h.v, slot);
  }

  // Stable (rotation-invariant, texel-snapped) box around one frustum slice.
  _cascade(cam, c, near, far, toSun) {
    const pts = [];
    for (const dist of [near, far]) for (const sx of [-1, 1]) for (const sy of [-1, 1]) {
      const hh = dist * c.th, hw = hh * c.aspect;
      pts.push([0, 1, 2].map(i => cam.pos[i] + c.fwd[i] * dist + c.right[i] * hw * sx + c.up[i] * hh * sy));
    }
    const ctr = [0, 1, 2].map(i => pts.reduce((s, p) => s + p[i], 0) / 8);
    const r = Math.ceil(Math.max(...pts.map(p => Math.hypot(p[0] - ctr[0], p[1] - ctr[1], p[2] - ctr[2]))) * 16) / 16;
    const v = lookAt([0, 0, 0], [-toSun[0], -toSun[1], -toSun[2]], Math.abs(toSun[1]) > 0.99 ? [1, 0, 0] : [0, 1, 0]);
    const cl = xform(v, ctr), texel = 2 * r / SHADOW_SIZE;
    v[12] -= Math.floor(cl[0] / texel) * texel; v[13] -= Math.floor(cl[1] / texel) * texel;
    return mul(ortho(-r, r, -r, r, -(cl[2] + r + REACH), r - cl[2]), v);
  }

  render(cam, env, time = 0) {
    const d = this.device, w = this.canvas.width, h = this.canvas.height;
    if (w !== this.w || h !== this.h) this._resize(w, h);
    const aspect = w / h, th = Math.tan(cam.fov / 2), toSun = norm(env.sunDir), f = new Float32Array(100);
    const fwd = [Math.sin(cam.yaw) * Math.cos(cam.pitch), Math.sin(cam.pitch), -Math.cos(cam.yaw) * Math.cos(cam.pitch)];
    const right = norm(cross(fwd, [0, 1, 0])), up = cross(right, fwd), c = { fwd, right, up, aspect, th };
    const view = lookAt(cam.pos, [cam.pos[0] + fwd[0], cam.pos[1] + fwd[1], cam.pos[2] + fwd[2]], [0, 1, 0]);
    f.set(mul(perspective(cam.fov, aspect, cam.near, cam.far), view), 0);
    const splits = [env.shadowDist * 0.08, env.shadowDist * 0.28, env.shadowDist]; let prev = cam.near;
    for (let i = 0; i < CASCADES; i++) {
      const m = this._cascade(cam, c, prev, splits[i], toSun);
      f.set(m, 16 + i * 16); d.queue.writeBuffer(this.cascadeBuf[i], 0, m); prev = splits[i];
    }
    f.set([...splits, 0], 64); f.set([...cam.pos, 0], 68); f.set([...right, 0], 72); f.set([...up, 0], 76); f.set([...fwd, 0], 80);
    f.set([th, aspect, time, 1 / SHADOW_SIZE], 84); f.set([...toSun, 0], 88); f.set([...env.sunColor, 0], 92); f.set([env.hazeDensity, this.skyMode, 0, 0], 96);
    d.queue.writeBuffer(this.frame, 0, f);

    const enc = d.createCommandEncoder();
    for (let i = 0; i < CASCADES; i++) {
      const q = enc.beginRenderPass({ colorAttachments: [], depthStencilAttachment: { view: this.shadowViews[i], depthClearValue: 1, depthLoadOp: 'clear', depthStoreOp: 'store' } });
      q.setPipeline(this.shadowPipe); q.setBindGroup(0, this.shadowBG[i]); this._draw(q); q.end();
    }
    const p = enc.beginRenderPass({ colorAttachments: [{ view: this.msaaV, resolveTarget: this.hdrV, clearValue: [0, 0, 0, 1], loadOp: 'clear', storeOp: 'discard' }],
      depthStencilAttachment: { view: this.depthV, depthClearValue: 1, depthLoadOp: 'clear', depthStoreOp: 'discard' } });
    p.setPipeline(this.scenePipe); p.setBindGroup(0, this.sceneBG); this._draw(p);
    p.setPipeline(this.skyPipe); p.setBindGroup(0, this.skyBG); p.draw(3);
    p.setPipeline(this.glassPipe); p.setBindGroup(0, this.glassBG); this._draw(p, true); p.end();      // glass last, blended over the sky and solids
    const fs = (pipe, bg, view, load) => {
      const q = enc.beginRenderPass({ colorAttachments: [{ view, loadOp: load ? 'load' : 'clear', clearValue: [0, 0, 0, 1], storeOp: 'store' }] });
      q.setPipeline(pipe); q.setBindGroup(0, bg); q.draw(3); q.end();
    };
    fs(this.pre, this.preBG, this.bloomV[0], false);
    for (let i = 0; i < BLOOM - 1; i++) fs(this.down, this.downBG[i], this.bloomV[i + 1], false);
    for (let i = BLOOM - 1; i > 0; i--) fs(this.up, this.upBG[i], this.bloomV[i - 1], true);
    fs(this.comp, this.compBG, this.ctx.getCurrentTexture().createView(), false);
    d.queue.submit([enc.finish()]);
  }
}










const canvas = document.getElementById('c'), hud = document.getElementById('hud'), $ = id => document.getElementById(id);
const fit = () => { const k = Math.min(devicePixelRatio || 1, 2); canvas.width = Math.max(1, innerWidth * k | 0); canvas.height = Math.max(1, innerHeight * k | 0); };
fit(); addEventListener('resize', fit);

// ---- Server: authoritative data model, physics, scripts. Everything the player sees arrives through the binary replication protocol.
const server = new DataModel(); buildDemoWorld(server); buildMeshDemo(server);
const physics = new PhysicsWorld(server), characters = new CharacterService(server, physics), net = new NetServer(server);
server.Players.PlayerAdded.Connect(p => characters.spawn(p, new Vector3(0, 8, 56)));          // every joining player gets a character
const out = $('out'), log = s => { out.textContent += s + '\n'; out.scrollTop = out.scrollHeight; };
const vm = new LuauHost(server, log); log('Luau: ' + vm.mode);
server.InstanceAdded.Connect(i => { if (i.ClassName === 'Script' && !i.Disabled && i.Source) vm.run(i.Source); });   // Scripts in the world run (sandboxed)
// ---- Client: an empty replica that fills from the snapshot, then follows deltas (40 ms simulated one-way latency).
const client = new DataModel(), [ct, st] = LoopbackTransport.pair({ latencyMs: 40, jitterMs: 25 }), netClient = new NetClient(client, ct); net.addClient(st, 'Local');
const cvm = new LuauHost(client, m => log('[client] ' + m));                       // a second Luau worker, running LocalScript-style code against the replica

const cam = { pos: [0, 12, 70], yaw: 0, pitch: -0.12, fov: 70 * Math.PI / 180, near: 0.2, far: 3000 };
const keys = new Set(); let speed = 20, gpuErr = '', skyNote = 'procedural sky', charMode = false, camDist = 14;
const setCharMode = on => { charMode = on; $('charBtn').style.background = on ? 'rgba(255,255,255,.22)' : ''; if (!on) netClient.sendInput(0, cam.yaw); };
$('charBtn').onclick = () => setCharMode(!charMode);
addEventListener('keydown', e => { if (e.target.tagName === 'TEXTAREA') return; keys.add(e.code); if (e.code === 'Space' && charMode) e.preventDefault(); if (e.code === 'KeyF' && !e.repeat) spawnCrate(); if (e.code === 'KeyC' && !e.repeat) setCharMode(!charMode); });
addEventListener('keyup', e => keys.delete(e.code));
canvas.addEventListener('contextmenu', e => e.preventDefault());
canvas.addEventListener('mousemove', e => { if (e.buttons & 3) { cam.yaw += e.movementX * 0.004; cam.pitch = Math.max(-1.5, Math.min(1.5, cam.pitch - e.movementY * 0.004)); } });
canvas.addEventListener('wheel', e => { if (charMode) camDist = Math.max(4, Math.min(40, camDist * (1 + Math.sign(e.deltaY) * 0.1))); else speed = Math.max(4, Math.min(200, speed * (1 - Math.sign(e.deltaY) * 0.1))); }, { passive: true });
const fwdOf = () => [Math.sin(cam.yaw) * Math.cos(cam.pitch), Math.sin(cam.pitch), -Math.cos(cam.yaw) * Math.cos(cam.pitch)];

function spawnCrate() {                                                          // runs on the server, like a script would
  const f = fwdOf(), p = createInstance('Part'), n = 2 + Math.random() * 2;
  p.Size = new Vector3(n, n, n); p.Position = new Vector3(cam.pos[0] + f[0] * 12, cam.pos[1] + f[1] * 12, cam.pos[2] + f[2] * 12);
  p.Color = Color3.fromHex([0xf5cd30, 0xc4281c, 0x0d69ac, 0x4b974b][Math.floor(Math.random() * 4)]); p.Studs = true; p.Roughness = 0.5; p.Parent = server.Workspace;
  const m = n * n * n * 0.7 * 60; physics.applyImpulse(p, new Vector3(f[0] * m, f[1] * m, f[2] * m));
}
const download = async (name, data) => {
  const dl = typeof claude !== 'undefined' ? await claude.use('downloads') : null;                   // hosted page: the viewer confirms the save
  if (dl) { try { await dl.save({ filename: name + '.txt', data }); log(`saved ${name}.txt (rename to ${name})`); } catch (e) { if (e.code !== 'declined') log('save failed: ' + (e.message || e.code)); } return; }
  const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([data])); a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);   // local copy keeps the real extension
};
const clearWorld = () => { for (const c of server.Workspace.GetChildren()) c.Destroy(); for (const c of server.ReplicatedStorage.GetChildren()) c.Destroy(); };
$('scriptBtn').onclick = () => $('panel').classList.toggle('show');
$('run').onclick = () => { log('> run (server)'); vm.run($('src').value); };
$('runc').onclick = () => { log('> run (client)'); cvm.run($('srcc').value); };
$('srcc').value = `-- Runs on the CLIENT replica. Run the server script first.
local rs = game:GetService("ReplicatedStorage")
local ping, add = rs:WaitForChild("Ping"), rs:WaitForChild("Add")
ping.OnClientEvent:Connect(function(m) print("client got", m) end)
ping:FireServer("hello")
print("2 + 3 =", add:InvokeServer(2, 3))   -- yields until the server answers`;
$('saveXml').onclick = () => download('world.cblx', serializeXml([server.Workspace, server.ReplicatedStorage, server.Lighting]));
$('saveBin').onclick = () => download('world.cbxm', encodeBinary([server.Workspace, server.ReplicatedStorage, server.Lighting]));
$('openBtn').onclick = () => $('openFile').click();
$('openFile').onchange = async () => {
  const f = $('openFile').files[0]; if (!f) return;
  try {
    clearWorld();
    const bytes = new Uint8Array(await f.arrayBuffer());
    if (bytes[0] === 0x43 && bytes[1] === 0x42 && bytes[2] === 0x58 && bytes[3] === 0x4d) await decodeBinaryAsync(bytes, { dm: server });   // 'CBXM' header = binary
    else loadXml(new TextDecoder().decode(bytes), { dm: server });
    log(`opened ${f.name}`);
  } catch (e) { log('open failed: ' + e.message); }
};
$('src').value = `-- Runs on the server in a sandbox. The client sees every change through binary replication.
local colors = { Color3.fromRGB(245, 205, 48), Color3.fromRGB(196, 40, 28), Color3.fromRGB(13, 105, 172) }
for i = 1, 8 do
  local ball = Instance.new("Part")
  ball.Shape = "Ball"
  ball.Size = Vector3.new(3, 3, 3)
  ball.Position = Vector3.new(-10 + i * 2.5, 20 + i * 5, 50)
  ball.Color = colors[i % 3 + 1]
  ball.Parent = workspace
  ball.Touched:Connect(function(other)
    if other.Name == "Baseplate" then ball.Metalness = 1 end
  end)
end
print("spawned 8 balls; workspace has", #workspace:GetDescendants(), "descendants")

-- 2 s: the house walls turn to glass (Transparency replicates and re-renders at once)
task.delay(2, function() workspace.House.Walls.Transparency = 0.6 end)
-- 4 s: an explosion. Nearby balls are destroyed (gone from rendering, physics and every client); other parts are thrown.
task.delay(4, function()
  local center = Vector3.new(0, 2, 45)
  for _, p in ipairs(workspace:GetDescendants()) do
    if p.ClassName == "Part" and not p.Anchored then
      local offset = p.Position - center
      if offset.Magnitude < 25 then
        if p.Shape == "Ball" and offset.Magnitude < 10 then p:Destroy() else p:ApplyImpulse(offset.Unit * 3000) end
      end
    end
  end
  print("boom")
end)

-- RemoteEvent / RemoteFunction (then press "Run on client")
local rs = game:GetService("ReplicatedStorage")
local ping = Instance.new("RemoteEvent") ping.Name = "Ping" ping.Parent = rs
local add = Instance.new("RemoteFunction") add.Name = "Add" add.Parent = rs
ping.OnServerEvent:Connect(function(player, msg) print("server got", msg, "from", player.Name) ping:FireClient(player, "pong") end)
add.OnServerInvoke = function(player, a, b) task.wait(0.3) return a + b end`;

try {
  const r = await Renderer.create(canvas); r.onError = e => { gpuErr = '\n⚠ GPU: ' + e.slice(0, 200); };
  const assets = new AssetProvider(r, { baseUrl: 'assets/' }); assets.onLog = log; client.GetService('ContentProvider').impl = assets; await mountDemoAssets(assets);
  const sync = new SceneSync(client, r, assets); assets.onChange = (k, kind) => sync.assetChanged(k, kind);       // renders the CLIENT replica
  const streamer = new AssetStreamer(client, assets, sync); let streamAcc = 1; window.crimblox = { assets, streamer, sync, cam, client, server, r };
  const file = $('skyFile');
  const loadSky = async f => { try { await r.setSkyboxFromBlob(f); skyNote = 'custom skybox: ' + f.name; } catch (e) { gpuErr = '\n⚠ Skybox: ' + e.message; } };
  $('skyBtn').onclick = () => file.click(); file.onchange = () => file.files[0] && loadSky(file.files[0]);
  $('skyReset').onclick = () => { r.setSkyboxProcedural(); skyNote = 'procedural sky'; };
  addEventListener('dragover', e => e.preventDefault());
  addEventListener('drop', e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f && f.type.startsWith('image/')) loadSky(f); });

  let last = performance.now(), acc = 0, frames = 0, lastBytes = 0, inputAcc = 0;
  const loop = now => {
    const dt = Math.min((now - last) / 1000, 0.1); last = now;
    const f = fwdOf();
    if (charMode) {                                                                                      // character: send input to the server, follow the replicated character
      inputAcc += dt; if (inputAcc >= 1 / 30) { inputAcc = 0; netClient.sendInput((keys.has('KeyW') ? 1 : 0) | (keys.has('KeyS') ? 2 : 0) | (keys.has('KeyA') ? 4 : 0) | (keys.has('KeyD') ? 8 : 0) | (keys.has('Space') ? 16 : 0), cam.yaw); }
      const root = client.Workspace.FindFirstChild(netClient.name)?.PrimaryPart;
      if (root) { const t = root.Position; cam.pos = [t.x - f[0] * camDist, Math.max(t.y + 2 - f[1] * camDist, 0.6), t.z - f[2] * camDist]; }
    } else {                                                                                             // free camera
      const sp = speed * (keys.has('ShiftLeft') ? 3 : 1) * dt, rt = [Math.cos(cam.yaw), 0, Math.sin(cam.yaw)], mv = (v, s) => { for (let i = 0; i < 3; i++) cam.pos[i] += v[i] * s; };
      if (keys.has('KeyW')) mv(f, sp); if (keys.has('KeyS')) mv(f, -sp); if (keys.has('KeyD')) mv(rt, sp); if (keys.has('KeyA')) mv(rt, -sp);
      if (keys.has('KeyE')) cam.pos[1] += sp; if (keys.has('KeyQ')) cam.pos[1] -= sp; cam.pos[1] = Math.max(cam.pos[1], 0.6);
    }
    vm.phase('stepped', dt); characters.step(dt); physics.step(dt); server.RunService._fire('Heartbeat', dt); vm.phase('heartbeat', dt); net.tick(dt);
    cvm.phase('stepped', dt); netClient.step(now / 1000); cvm.phase('heartbeat', dt);                 // client frame: interpolate replicated parts, then client scripts            // server frame
    if ((streamAcc += dt) > 0.25) { streamAcc = 0; streamer.tick(cam.pos, now / 1000); assets.tick(); client.GetService('ContentProvider').RequestQueueSize = assets.queueSize; }   // LOD streaming runs 4x a second
    sync.flush();                                                                                      // client: push replicated changes to the GPU
    const L = client.Lighting, d = L.SunDirection, c = L.SunColor, b = L.Brightness;
    r.render(cam, { sunDir: [d.x, d.y, d.z], sunColor: [c.r * b, c.g * b, c.b * b], hazeDensity: L.HazeDensity, shadowDist: L.ShadowDistance }, now / 1000);
    acc += dt; frames++;
    if (acc > 0.5) {
      const kb = (netClient.bytesIn - lastBytes) / acc / 1024; lastBytes = netClient.bytesIn;
      hud.textContent = `${(frames / acc).toFixed(0)} fps · ${sync.partCount} parts · ${physics.stats.bodies} bodies, ${physics.stats.contacts} contacts · net ${kb.toFixed(1)} KB/s · ${assets.summary()} · streamer ${streamer.stats.held}/${streamer.stats.tracked} held, ${streamer.stats.occluded} walled · ${skyNote}\n${charMode ? 'CHARACTER: WASD move · Space jump · drag to look · wheel zoom' : 'FREE CAMERA: WASD move · Q/E down/up · Shift fast · wheel speed'} · C toggles · F throws a crate${gpuErr}`;
      acc = 0; frames = 0;
    }
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
} catch (e) { hud.textContent = 'Error: ' + e.message; console.error(e); }
